        // ---------------- 3: PENALTILAR ----------------
        m(3, 1, "How far does the penalty area extend from the goal line into the field?",
            "Ceza sahası kale çizgisinden sahanın içine doğru kaç metre uzanır?",
            listOf("5.5 m", "9.15 m", "16.5 m", "18.5 m"), listOf("5,5 m", "9,15 m", "16,5 m", "18,5 m"), 2,
            "The penalty area extends 16.5 m from each goalpost into the field and 16.5 m from the goal line.",
            "Ceza sahası, her direkten 16,5 m yana ve kale çizgisinden 16,5 m ileri uzanır."),
        m(3, 2, "Where must all players other than the kicker and goalkeeper stand during a penalty kick?",
            "Penaltı atışında vurucu ve kaleci dışındaki tüm oyuncular nerede durmalıdır?",
            listOf("Outside the penalty area, behind the penalty mark and at least 9.15 m from it", "Inside the penalty arc only", "On the goal line", "On the halfway line"),
            listOf("Ceza sahasının dışında, penaltı noktasının gerisinde ve noktadan en az 9,15 m uzakta", "Sadece penaltı yayının içinde", "Kale çizgisinde", "Orta çizgide"), 0,
            "They must be outside the penalty area, behind the penalty mark and at least 9.15 m from the mark.",
            "Ceza sahası dışında, penaltı noktasının gerisinde ve noktadan en az 9,15 m uzakta olmalıdırlar."),
        m(3, 2, "The goalkeeper saves a penalty and the ball rebounds to the kicker, who scores. Decision?",
